// employee_id -> {email, mail_key} (mail_key из n8n Variables, не хардкодить)
const MANAGER_EMAIL_MAPPING = {
  "1137861": {
    email: "manager1@example.com",
    mail_key: $vars.MANAGER1_MAIL_KEY
  },
  "1129956": {
    email: "manager2@example.com",
    mail_key: $vars.MANAGER2_MAIL_KEY
  }
};

const employeeId = String($input.item.json.employee_id || '');
const managerData = MANAGER_EMAIL_MAPPING[employeeId];
const managerEmail = managerData?.email || '0';
const managerMailKey = managerData?.mail_key || '0';

return {
  ...($input.item.json),
  manager_email: managerEmail,
  manager_mail_key: managerMailKey,
  manager_email_source: managerData ? 'mapping' : 'default'
};

const crmData = $('Map Manager Email').item.json;

// Собираем все входные items
const inputItems = $('IMAP Search').all();

// Разворачиваем все письма из ответов микросервиса
const allEmails = inputItems
  .flatMap(item => {
    const emails = item.json.emails || [];
    return Array.isArray(emails) ? emails : [];
  })
  .map(email => {
    const dateStr = email.date || new Date().toISOString();

    let timestamp = 0;
    const parsed = new Date(dateStr).getTime();
    if (!Number.isNaN(parsed)) {
      timestamp = parsed;
    }

    const fromValue = email.from || '';
    const toValue = email.to || '';
    const subjectValue = email.subject || 'No subject';
    const bodyValue = email.text_plain || '';
    const clientEmail = (crmData.client_email || '').toLowerCase();
    const fromLower = fromValue.toLowerCase();

    return {
      from: fromValue,
      to: toValue,
      subject: subjectValue,
      date: dateStr,
      body: bodyValue,
      timestamp,
      direction: fromLower.includes(clientEmail) ? 'FROM_CLIENT' : 'TO_CLIENT',
    };
  })
  .sort((a, b) => a.timestamp - b.timestamp);

// Форматируем историю переписки
const emailHistory = allEmails.map((email, index) => {
  const direction = email.direction === 'FROM_CLIENT' ? 'CLIENT' : 'MANAGER';

  return `=== EMAIL #${index + 1} [${direction}] ===
From: ${email.from}
To: ${email.to}
Date: ${email.date}
Subject: ${email.subject}

${email.body}
========================`;
}).join('\n\n');

return [
  {
    json: {
      ...crmData,
      email_history: emailHistory,
      email_count: allEmails.length,
      last_email_date: allEmails[allEmails.length - 1]?.date || 'N/A',
    }
  }
];

const emails = $input.first()?.json?.emails ?? [];

if (emails.length > 0) {
  // Ищем последнее письмо с непустым текстом
  const lastWithText = [...emails]
    .reverse()
    .find(e => e.text_plain && e.text_plain.trim() !== "");

  const text_plain = lastWithText?.text_plain ?? null;
  return text_plain ? [{ json: { text_plain } }] : [];
} else {
  const fallback = $('Extract Deal Data').first().json.first_message_from_client;
  return fallback ? [{ json: { text_plain: fallback } }] : [];
}
